1	import { NextResponse } from "next/server";
2	import { cookieName, tokenPruefen } from "@/lib/plattform/sitzung";
3	import { LAND_COOKIE } from "@/lib/land/vorschlag";
4	import { SPRACH_COOKIE } from "@/lib/sprache/sprachen";
5	import { startseitenZiel } from "@/lib/land/vorschlag";
6	
7	// Portal-Schutz: /portal/** nur mit gültig signiertem Sitzungscookie, sonst
8	// Weiterleitung zu /login?weiter=… (nur interne Pfade). Die Middleware prüft
9	// Signatur und Ablauf; Rollen, Sperre und Sitzungsversion prüfen Seiten und
10	// APIs bei jedem Aufruf frisch gegen das Backend.
11	// Sichere Kopfzeilen für Portal, Anmeldung, Einladungen und Plattform-APIs (Login, Sicherheit & Teams):
12	// kein Einbetten (Clickjacking), eigener Browsing-Kontext, kein Referrer bei Token-Links, HSTS in Produktion.
13	function sicherheitsKopf(res, pathname) {
14	  const h = res.headers;
15	  h.set("X-Frame-Options", "DENY");
16	  h.set("Content-Security-Policy", "frame-ancestors 'none'; base-uri 'self'; form-action 'self'; object-src 'none'");
17	  h.set("Cross-Origin-Opener-Policy", "same-origin");
18	  h.set("X-Content-Type-Options", "nosniff");
19	  h.set("Permissions-Policy", "camera=(), microphone=(), geolocation=(self), payment=(), usb=()");
20	  const tokenSeite = ["/login/link", "/einladung/", "/passwort-vergessen", "/api/auth/"].some((p) => pathname.startsWith(p));
21	  h.set("Referrer-Policy", tokenSeite ? "no-referrer" : "strict-origin-when-cross-origin");
22	  if (!pathname.startsWith("/api/")) h.set("Cache-Control", "no-store");
23	  if (process.env.NODE_ENV === "production") h.set("Strict-Transport-Security", "max-age=63072000; includeSubDomains");
24	  return res;
25	}
26	
27	// Länder- und Sprachmodell: Die Startseite „/“ leitet NUR mit gesetztem Cookie „land“ bzw.
28	// „sprache“ (entstehen erst nach aktiver Wahl in der Kopfleiste) auf die gespeicherte Wahl um:
29	// land=AT → /at, sprache=en → /en, beides → /en/at. Ohne Cookie – auch für Suchmaschinen – nie.
30	// Keine Auswertung von IP oder Browsersprache. Die Antwort auf „/“ wird nie zwischengespeichert
31	// (private, no-store; Vary: Cookie), weder mit noch ohne Weiterleitung. Unterseiten leiten nie um.
32	function startseite(request) {
33	  const ziel = startseitenZiel(request.cookies.get(LAND_COOKIE)?.value, request.cookies.get(SPRACH_COOKIE)?.value);
34	  const res = ziel ? NextResponse.redirect(new URL(ziel + request.nextUrl.search, request.url), 307) : NextResponse.next();
35	  res.headers.set("Cache-Control", "private, no-store, max-age=0");
36	  res.headers.set("Vary", "Cookie");
37	  return res;
38	}
39	
40	export async function middleware(request) {
41	  const { pathname, search } = request.nextUrl;
42	  if (pathname === "/") return startseite(request);
43	  // Nicht-Portal-Pfade (Anmeldung, Einladung, APIs): nur Kopfzeilen, keine Sitzungsprüfung hier
44	  if (pathname !== "/portal" && !pathname.startsWith("/portal/")) return sicherheitsKopf(NextResponse.next(), pathname);
45	  const token = request.cookies.get(cookieName())?.value;
46	
47	  let gueltig = false;
48	  try {
49	    gueltig = !!(await tokenPruefen(token));
50	  } catch (e) {
51	    // z. B. SESSION_SECRET fehlt in Produktion – nie ohne Prüfung durchlassen
52	    console.error("[plattform] Sitzungsprüfung fehlgeschlagen:", e?.message);
53	  }
54	
55	  if (!gueltig) {
56	    const ziel = new URL("/login", request.url);
57	    ziel.searchParams.set("weiter", `${pathname}${search}`.slice(0, 300));
58	    const res = NextResponse.redirect(ziel);
59	    if (token) res.cookies.delete(cookieName());
60	    return sicherheitsKopf(res, pathname);
61	  }
62	
63	  // Aktuellen Pfad an Server-Komponenten weiterreichen (für ?weiter= bei abgelaufener Sitzung)
64	  const kopf = new Headers(request.headers);
65	  kopf.set("x-oi-pfad", `${pathname}${search}`.slice(0, 300));
66	  return sicherheitsKopf(NextResponse.next({ request: { headers: kopf } }), pathname);
67	}
68	
69	export const config = {
70	  matcher: ["/", "/portal", "/portal/:path*", "/login", "/login/:path*", "/registrieren", "/passwort-vergessen", "/einladung/:path*", "/api/auth/:path*", "/api/portal/:path*"],
71	};
