  const url = new URL(request.url);
  const q = url.searchParams;
  const html = widgetDokument({
    widgetId: "fristen",
    land: widgetLand(q.get("land"), "fristen"),
    sprache: widgetSprache(q.get("sprache")),
    partner: widgetPartner(q.get("partner")),
