                  src={vorschau}
                  title={`${en ? w.titelEn : w.titel} – ÖkoInvest`}
                  width="100%"
                  height={w.hoehe}
                  loading="lazy"
                  className="w-full rounded-2xl ring-1 ring-ink-200/70"
                  style={{ border: 0 }}
