              <p.icon aria-hidden="true" className="h-6 w-6 text-ov-600" />
              <h3 className="mt-3 font-display text-[16px] font-bold text-ink-900">{p.t}</h3>
              <p className="mt-2 text-[14px] leading-relaxed text-ink-600">{p.s}</p>
